// Prepare input Markdown buffer (MD_CHAR units) from fuzz data while respecting size constraints.
std::string raw = FUZZ_PARAM_STR();
size_t unit_bytes = sizeof(MD_CHAR);
// Limit total MD_CHAR units to keep allocations small.
size_t max_units_from_src = raw.size() / (unit_bytes ? unit_bytes : 1);
size_t n_units = max_units_from_src;
if (n_units > 1024) n_units = 1024;
// Always keep a non-null data pointer even for size==0 to satisfy APIs expecting readable pointer when size>0
std::vector<MD_CHAR> buf(n_units > 0 ? n_units : 1);
// Copy raw bytes into MD_CHAR buffer without assuming encoding; parser will treat them as MD_CHAR code units.
for (size_t i = 0; i < n_units; ++i) {
    const unsigned char* src = reinterpret_cast<const unsigned char*>(raw.data()) + i * unit_bytes;
    MD_CHAR val = MD_CHAR();
    // Copy byte-for-byte into the MD_CHAR slot.
    std::memcpy(&val, src, unit_bytes);
    buf[i] = val;
}
const MD_CHAR* text = buf.data();
