// Userdata/state shared across callbacks to exercise abort path and basic invariants.
struct State {
    int should_abort;
    int aborted;
    int abort_code; // non-zero when used to abort
    unsigned blocks_entered;
    unsigned blocks_left;
    unsigned spans_entered;
    unsigned spans_left;
    unsigned text_calls;
} state;
state.should_abort = (int)(*FUZZ_PARAM(unsigned) & 1); // randomly decide to request an abort from a callback
state.aborted = 0;
state.abort_code = 1 + (int)(*FUZZ_PARAM(unsigned) % 3); // [1..3]
state.blocks_entered = state.blocks_left = state.spans_entered = state.spans_left = state.text_calls = 0;
// Define callbacks (non-capturing lambdas convert to function pointers) matching MD_PARSER signature.
auto cb_enter_block = [](MD_BLOCKTYPE, void* /*detail*/, void* ud) -> int {
    State* st = static_cast<State*>(ud);
    st->blocks_entered++;
    if (st->should_abort && !st->aborted) { st->aborted = 1; return st->abort_code; }
    return 0;
};
auto cb_leave_block = [](MD_BLOCKTYPE, void* /*detail*/, void* ud) -> int {
    State* st = static_cast<State*>(ud);
    st->blocks_left++;
    if (st->should_abort && !st->aborted) { st->aborted = 1; return st->abort_code; }
    return 0;
};
auto cb_enter_span = [](MD_SPANTYPE, void* /*detail*/, void* ud) -> int {
    State* st = static_cast<State*>(ud);
    st->spans_entered++;
    if (st->should_abort && !st->aborted) { st->aborted = 1; return st->abort_code; }
    return 0;
};
auto cb_leave_span = [](MD_SPANTYPE, void* /*detail*/, void* ud) -> int {
    State* st = static_cast<State*>(ud);
    st->spans_left++;
    if (st->should_abort && !st->aborted) { st->aborted = 1; return st->abort_code; }
    return 0;
};
auto cb_text = [](MD_TEXTTYPE /*type*/, const MD_CHAR* txt, MD_SIZE sz, void* ud) -> int {
    State* st = static_cast<State*>(ud);
    // Honor size: do not assume zero-termination; only touch up to sz units if we inspect.
    (void)txt; (void)sz;
    st->text_calls++;
    if (st->should_abort && !st->aborted) { st->aborted = 1; return st->abort_code; }
    return 0;
};
auto cb_debug = [](const char* /*msg*/, void* /*ud*/) -> void {
    // Optional; do nothing but accept calls.
};
// Construct MD_PARSER with required invariants enforced: abi_version==0, syntax==NULL.
MD_PARSER parser;
std::memset(&parser, 0, sizeof(parser));
parser.abi_version = 0; // required reserved value
parser.flags = *FUZZ_PARAM(unsigned); // random dialect/feature flags bitmask
parser.enter_block = cb_enter_block;
parser.leave_block = cb_leave_block;
parser.enter_span  = cb_enter_span;
parser.leave_span  = cb_leave_span;
parser.text        = cb_text;
parser.debug_log   = (int)(*FUZZ_PARAM(unsigned)&1) ? cb_debug : nullptr; // optional
parser.syntax      = nullptr; // must be NULL per API
